 labs:[['carbonato',{pka1:6.301,pka2:10.301},b('Karbonatoaren espezie-banaketa','Distribución de especies del carbonato')],['valoracion',{ka:1.8e-5},b('Azido sendo/ahul baten balorazioa','Valoración de ácido fuerte/débil')]],
 intro:[['p',b('<b>Lehentasun handia azterketarako.</b> Diagnostikoan azido-basea 10 azterketatik 9tan agertzen da, maiz Kps/prezipitazioarekin eta elektrokimikarekin konbinatuta. Karbonatoa lau deialditan agertu da. Ikasi mol-balantzea eta espezieen oreka batera erabiltzen.','<b>Prioridad alta para el examen.</b> El diagnóstico encuentra ácido-base en 9 de 10 exámenes, a menudo combinado con Kps/precipitación y electroquímica. El carbonato aparece en cuatro convocatorias. Aprende a combinar balance de moles y equilibrio de especies.')],['p',b('Ikasketa-ordena: definizioak eta pH → indar erlatiboa → oreka-kalkuluak → gatzak eta nahasteak → bufferra → karbonatoa. Azterketa-datuak apunteetako balio orokorren gainetik daude.','Orden de estudio: definiciones y pH → fuerza relativa → cálculos de equilibrio → sales y mezclas → tampón → carbonato. Los datos del examen prevalecen sobre los valores generales de los apuntes.')]],
 vocab:[['ácido','azidoa'],['base','basea'],['protón','protoia'],['pareja conjugada','bikote konjokatua'],['base conjugada','base konjokatua'],['ácido conjugado','azido konjokatua'],['ácido fuerte','azido sendoa'],['ácido débil','azido ahula'],['muy débil','oso ahula'],['constante de acidez','azidotasun-konstantea'],['constante de basicidad','basikotasun-konstantea'],['autoionización del agua','uraren autoionizazioa'],['producto iónico','produktu ionikoa'],['grado de disociación','disoziazio-gradua'],['tabla ICE','ICE taula'],['neutralización','neutralizazioa'],['ion espectador','ioi ikuslea'],['sal','gatza'],['hidrólisis','hidrolisia'],['disolución amortiguadora','disoluzio indargetzailea'],['reacción significativa','erreakzio esanguratsua'],['anfótero','anfoteroa'],['carbonato','karbonatoa'],['bicarbonato','bikarbonatoa'],['punto de equivalencia','baliokidetasun-puntua'],['capacidad amortiguadora','indargetze-gaitasuna'],['precipitación','hauspeatzea']],
